package th.samo.adventureeconomy;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.*;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.EntityArgument;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.Level;
import java.util.*;

public final class RPGCommands {
 private RPGCommands(){}
 private static void msg(CommandSourceStack s,String m){s.sendSuccess(()->Component.literal(m),false);}
 private static RPGData data(CommandSourceStack s){return RPGData.get(s.getServer());}
 private static EconomyData eco(CommandSourceStack s){return EconomyData.get(s.getServer());}
 private static ServerPlayer self(CommandSourceStack s)throws com.mojang.brigadier.exceptions.CommandSyntaxException{return s.getPlayerOrException();}
 private static boolean charge(ServerPlayer p,long n){var a=EconomyData.get(p.getServer()).account(p.getUUID());if(n<0||a.wallet<n)return false;a.wallet-=n;EconomyData.get(p.getServer()).setDirty();return true;}
 private static void credit(ServerPlayer p,long n){credit(p.getServer(),p.getUUID(),n);}
 private static void credit(net.minecraft.server.MinecraftServer server,UUID id,long n){EconomyData d=EconomyData.get(server);d.account(id).wallet+=n;d.setDirty();}
 private static void give(ServerPlayer p,ItemStack stack){if(!p.getInventory().add(stack.copy()))p.drop(stack.copy(),false);}
 private static void removeItems(ServerPlayer p,net.minecraft.world.item.Item item,int amount){
  int left=amount;
  for(int i=0;i<p.getInventory().getContainerSize()&&left>0;i++){
   ItemStack slot=p.getInventory().getItem(i);
   if(!slot.isEmpty()&&slot.getItem()==item){int take=Math.min(left,slot.getCount());slot.shrink(take);left-=take;}
  }
 }
 private static String itemName(ItemStack s){return s.getHoverName().getString();}
 public static void register(CommandDispatcher<CommandSourceStack> d){
  d.register(Commands.literal("market")
   .then(Commands.literal("sell").then(Commands.argument("price",LongArgumentType.longArg(1)).executes(c->{
    ServerPlayer p=self(c.getSource());if(!data(c.getSource()).player(p.getUUID()).getBoolean("shopOpen"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ร้านปิดอยู่ ใช้ /shop open ก่อน")).create();ItemStack hand=p.getMainHandItem();if(hand.isEmpty())throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ถือไอเทมที่ต้องการขายก่อน")).create();
    ItemStack sold=hand.copy();hand.setCount(0);CompoundTag t=new CompoundTag();t.putInt("id",data(c.getSource()).nextId());t.putUUID("owner",p.getUUID());t.put("stack",sold.save(new CompoundTag()));t.putLong("price",LongArgumentType.getLong(c,"price"));t.putString("type","market");t.putString("seller",p.getGameProfile().getName());data(c.getSource()).listings.add(t);data(c.getSource()).setDirty();msg(c.getSource(),"ลงขาย #"+t.getInt("id")+" "+itemName(sold)+" x"+sold.getCount()+" ราคา "+t.getLong("price")+" G");return 1;
   })))
   .then(Commands.literal("list").executes(c->{for(CompoundTag t:data(c.getSource()).listings)if(t.getString("type").equals("market"))msg(c.getSource(),"#"+t.getInt("id")+" "+t.getString("seller")+" | "+ItemStack.of(t.getCompound("stack")).getHoverName().getString()+" x"+ItemStack.of(t.getCompound("stack")).getCount()+" | "+t.getLong("price")+" G");return 1;}))
   .then(Commands.literal("buy").then(Commands.argument("id",IntegerArgumentType.integer(1)).executes(c->{
    int id=IntegerArgumentType.getInteger(c,"id");RPGData rd=data(c.getSource());CompoundTag t=rd.listing(id);ServerPlayer p=self(c.getSource());
    if(t==null||!t.getString("type").equals("market"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ไม่พบรายการ")).create();
    if(t.getUUID("owner").equals(p.getUUID()))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ซื้อสินค้าตัวเองไม่ได้")).create();
    long price=t.getLong("price");if(!charge(p,price))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("Wallet ไม่เพียงพอ")).create();
    ItemStack stack=ItemStack.of(t.getCompound("stack"));give(p,stack);long tax=(long)Math.floor(price*rd.taxRate);credit(c.getSource().getServer(),t.getUUID("owner"),price-tax);rd.treasury+=tax;rd.listings.remove(t);rd.setDirty();msg(c.getSource(),"ซื้อสำเร็จ ภาษี "+tax+" G");return 1;
   }))));
  d.register(Commands.literal("shop")
   .then(Commands.literal("name").then(Commands.argument("name",StringArgumentType.greedyString()).executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());t.putString("shopName",StringArgumentType.getString(c,"name"));data(c.getSource()).setDirty();msg(c.getSource(),"ตั้งชื่อร้านแล้ว");return 1;})))
   .then(Commands.literal("open").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());t.putBoolean("shopOpen",true);data(c.getSource()).setDirty();msg(c.getSource(),"เปิดร้านแล้ว");return 1;}))
   .then(Commands.literal("close").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());t.putBoolean("shopOpen",false);data(c.getSource()).setDirty();msg(c.getSource(),"ปิดร้านแล้ว");return 1;}))
   .then(Commands.literal("status").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());msg(c.getSource(),"Shop: "+t.getString("shopName")+" | "+(t.getBoolean("shopOpen")?"OPEN":"CLOSED")+" | ลงสินค้าใช้ /market sell <price>");return 1;})));
  d.register(Commands.literal("auction")
   .then(Commands.literal("create").then(Commands.argument("startPrice",LongArgumentType.longArg(1)).then(Commands.argument("minutes",IntegerArgumentType.integer(1,10080)).executes(c->{
    ServerPlayer p=self(c.getSource());ItemStack h=p.getMainHandItem();if(h.isEmpty())throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ถือไอเทมก่อน")).create();
    ItemStack st=h.copy();h.setCount(0);CompoundTag t=new CompoundTag();t.putInt("id",data(c.getSource()).nextId());t.putUUID("owner",p.getUUID());t.put("stack",st.save(new CompoundTag()));t.putLong("price",LongArgumentType.getLong(c,"startPrice"));t.putLong("end",p.level().getGameTime()+IntegerArgumentType.getInteger(c,"minutes")*1200L);t.putString("type","auction");t.putString("seller",p.getGameProfile().getName());data(c.getSource()).listings.add(t);data(c.getSource()).setDirty();msg(c.getSource(),"สร้างประมูล #"+t.getInt("id"));return 1;
   }))))
   .then(Commands.literal("list").executes(c->{for(CompoundTag t:data(c.getSource()).listings)if(t.getString("type").equals("auction"))msg(c.getSource(),"#"+t.getInt("id")+" "+itemName(ItemStack.of(t.getCompound("stack")))+" | bid "+t.getLong("price")+" G | end "+t.getLong("end"));return 1;}))
   .then(Commands.literal("bid").then(Commands.argument("id",IntegerArgumentType.integer(1)).then(Commands.argument("amount",LongArgumentType.longArg(1)).executes(c->{
    CompoundTag t=data(c.getSource()).listing(IntegerArgumentType.getInteger(c,"id"));ServerPlayer p=self(c.getSource());long n=LongArgumentType.getLong(c,"amount");
    if(t==null||!t.getString("type").equals("auction")||p.level().getGameTime()>t.getLong("end")||n<=t.getLong("price"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ประมูลไม่เปิดหรือราคาต้องสูงกว่าปัจจุบัน")).create();
    if(eco(c.getSource()).account(p.getUUID()).wallet<n)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("Wallet ไม่พอสำหรับราคาเสนอ")).create();
    t.putLong("price",n);t.putUUID("bidder",p.getUUID());t.putString("bidderName",p.getGameProfile().getName());data(c.getSource()).setDirty();msg(c.getSource(),"เสนอราคา "+n+" G สำเร็จ");return 1;
   }))))
   .then(Commands.literal("claim").then(Commands.argument("id",IntegerArgumentType.integer(1)).executes(c->{
    RPGData rd=data(c.getSource());CompoundTag t=rd.listing(IntegerArgumentType.getInteger(c,"id"));ServerPlayer seller=self(c.getSource());
    if(t==null||!t.getString("type").equals("auction")||!t.getUUID("owner").equals(seller.getUUID())||seller.level().getGameTime()<t.getLong("end"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ยังรับผลประมูลไม่ได้")).create();
    if(t.hasUUID("bidder")){ServerPlayer winner=c.getSource().getServer().getPlayerList().getPlayer(t.getUUID("bidder"));if(winner==null)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ผู้ชนะต้องออนไลน์เพื่อรับสินค้า")).create();if(!charge(winner,t.getLong("price")))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ผู้ชนะมีเงินไม่พอแล้ว")).create();give(winner,ItemStack.of(t.getCompound("stack")));long tax=(long)(t.getLong("price")*rd.taxRate);credit(c.getSource().getServer(),seller.getUUID(),t.getLong("price")-tax);rd.treasury+=tax;}else give(seller,ItemStack.of(t.getCompound("stack")));
    rd.listings.remove(t);rd.setDirty();msg(c.getSource(),"ปิดประมูลเรียบร้อย");return 1;
   }))));
  d.register(Commands.literal("merchant")
   .then(Commands.literal("catalog").executes(c->{msg(c.getSource(),"Food: bread 5, cooked_beef 12, apple 8 | Ore: iron_ingot 20, gold_ingot 35, diamond 250, coal 4 | Blocks: oak_planks 2, stone 2, glass 5 | Alchemist: potion 80 | Equipment: iron_sword 120, iron_chestplate 220 | Black Market: golden_apple 500, ender_pearl 150");return 1;}))
   .then(Commands.literal("buy").then(Commands.argument("item",StringArgumentType.word()).then(Commands.argument("amount",IntegerArgumentType.integer(1,64)).executes(c->{
    ServerPlayer p=self(c.getSource());String name=StringArgumentType.getString(c,"item");int n=IntegerArgumentType.getInteger(c,"amount");
    net.minecraft.resources.ResourceLocation key=net.minecraft.resources.ResourceLocation.tryParse("minecraft:"+name);
    net.minecraft.world.item.Item item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(key);
    if(item==Items.AIR)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ไม่พบสินค้าในแคตตาล็อก")).create();
    Map<String,Long> prices=Map.ofEntries(Map.entry("bread",5L),Map.entry("cooked_beef",12L),Map.entry("apple",8L),Map.entry("iron_ingot",20L),Map.entry("gold_ingot",35L),Map.entry("diamond",250L),Map.entry("coal",4L),Map.entry("oak_planks",2L),Map.entry("stone",2L),Map.entry("glass",5L),Map.entry("potion",80L),Map.entry("iron_sword",120L),Map.entry("iron_chestplate",220L),Map.entry("golden_apple",500L),Map.entry("ender_pearl",150L));
    Long unit=prices.get(name);if(unit==null)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("สินค้านี้ไม่ได้อยู่ในรายการขาย")).create();
    if(name.equals("golden_apple")&&data(c.getSource()).player(p.getUUID()).getInt("blackRep")<5)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ต้องมี Black Market reputation 5 ก่อน")).create();
    long total=unit*n;if(!charge(p,total))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("Wallet ไม่เพียงพอ")).create();
    give(p,new ItemStack(item,n));data(c.getSource()).treasury+=(long)(total*data(c.getSource()).taxRate);data(c.getSource()).setDirty();msg(c.getSource(),"ซื้อ "+name+" x"+n+" ราคา "+total+" G");return 1;
   }))))
   .then(Commands.literal("sell").then(Commands.argument("item",StringArgumentType.word()).then(Commands.argument("amount",IntegerArgumentType.integer(1,64)).executes(c->{
    ServerPlayer p=self(c.getSource());String name=StringArgumentType.getString(c,"item");int n=IntegerArgumentType.getInteger(c,"amount");
    net.minecraft.world.item.Item item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.tryParse("minecraft:"+name));
    if(item==Items.AIR||p.getInventory().countItem(item)<n)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ไม่มีไอเทมหรือจำนวนไม่พอ")).create();
    long unit=switch(name){case "bread"->2;case "cooked_beef"->5;case "apple"->3;case "iron_ingot"->8;case "gold_ingot"->14;case "diamond"->100;case "coal"->1;case "oak_planks","stone"->1;default->0;};
    if(unit==0)throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("NPC ไม่รับซื้อไอเทมนี้")).create();
    removeItems(p,item,n);long total=unit*n;credit(p,total);data(c.getSource()).player(p.getUUID()).putInt("merchantRep",data(c.getSource()).player(p.getUUID()).getInt("merchantRep")+1);data(c.getSource()).setDirty();msg(c.getSource(),"ขาย "+name+" x"+n+" ได้ "+total+" G");return 1;
   })))));
  d.register(Commands.literal("guild")
   .then(Commands.literal("join").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());t.putBoolean("guild",true);t.putInt("rank",0);data(c.getSource()).setDirty();msg(c.getSource(),"สมัครกิลด์สำเร็จ แรงก์ F");return 1;}))
   .then(Commands.literal("status").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());String[] r={"F","E","D","C","B","A","S"};msg(c.getSource(),t.getBoolean("guild")?"Guild rank "+r[Math.max(0,Math.min(6,t.getInt("rank")))]+", reputation "+t.getInt("guildRep"):"ยังไม่ได้เข้าร่วมกิลด์");return 1;}))
   .then(Commands.literal("promote").requires(s->s.hasPermission(2)).then(Commands.argument("player",EntityArgument.player()).then(Commands.argument("rank",IntegerArgumentType.integer(0,6)).executes(c->{ServerPlayer p=EntityArgument.getPlayer(c,"player");var t=data(c.getSource()).player(p.getUUID());t.putBoolean("guild",true);t.putInt("rank",IntegerArgumentType.getInteger(c,"rank"));data(c.getSource()).setDirty();msg(c.getSource(),"ตั้งแรงก์ให้ "+p.getName().getString()+" แล้ว");return 1;})))));
  d.register(Commands.literal("quest")
   .then(Commands.literal("list").executes(c->{msg(c.getSource(),"Available: hunt_skeleton (ฆ่า Skeleton 10 ตัว), gather_iron (เก็บ Iron Ore 32 ก้อน)");return 1;}))
   .then(Commands.literal("accept").then(Commands.argument("quest",StringArgumentType.word()).executes(c->{ServerPlayer p=self(c.getSource());var t=data(c.getSource()).player(p.getUUID());if(!t.getBoolean("guild"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ต้องเข้ากิลด์ก่อน")).create();String q=StringArgumentType.getString(c,"quest");if(!q.equals("hunt_skeleton")&&!q.equals("gather_iron"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ไม่มีเควสนี้")).create();t.putString("quest",q);t.putInt("questProgress",0);t.putBoolean("questClaimed",false);data(c.getSource()).setDirty();msg(c.getSource(),"รับเควส "+q+" แล้ว");return 1;})))
   .then(Commands.literal("status").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());msg(c.getSource(),"Quest "+t.getString("quest")+" : "+t.getInt("questProgress")+"/ "+(t.getString("quest").equals("hunt_skeleton")?10:32));return 1;}))
   .then(Commands.literal("claim").executes(c->{ServerPlayer p=self(c.getSource());var t=data(c.getSource()).player(p.getUUID());String q=t.getString("quest");int goal=q.equals("hunt_skeleton")?10:32;if(q.isEmpty()||t.getInt("questProgress")<goal||t.getBoolean("questClaimed"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("เควสยังไม่สำเร็จหรือรับรางวัลแล้ว")).create();t.putBoolean("questClaimed",true);t.putInt("guildRep",t.getInt("guildRep")+10);credit(p,250);data(c.getSource()).setDirty();msg(c.getSource(),"รับรางวัล 250 G และ Guild reputation +10");return 1;})));
  d.register(Commands.literal("gamble")
   .then(Commands.literal("chest").then(Commands.argument("bet",LongArgumentType.longArg(1)).executes(c->{ServerPlayer p=self(c.getSource());long bet=LongArgumentType.getLong(c,"bet");if(bet<500||!charge(p,bet))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ต้องเดิมพันอย่างน้อย 500 G และมีเงินเพียงพอ")).create();int roll=p.getRandom().nextInt(100);ItemStack prize=roll<50?new ItemStack(Items.BREAD,8):roll<80?new ItemStack(Items.IRON_INGOT,8):roll<95?new ItemStack(Items.DIAMOND,2):roll<99?new ItemStack(Items.GOLDEN_APPLE,3):new ItemStack(Items.NETHERITE_INGOT);give(p,prize);msg(c.getSource(),"Lucky Chest: "+(roll<50?"Common":roll<80?"Uncommon":roll<95?"Rare":roll<99?"Epic":"Legendary")+" ได้ "+prize.getCount()+" "+itemName(prize));return 1;})))
   .then(Commands.literal("dice").then(Commands.argument("bet",LongArgumentType.longArg(1)).then(Commands.argument("guess",IntegerArgumentType.integer(1,6)).executes(c->{ServerPlayer p=self(c.getSource());long bet=LongArgumentType.getLong(c,"bet");if(!charge(p,bet))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("เงินไม่พอ")).create();int n=p.getRandom().nextInt(6)+1,g=IntegerArgumentType.getInteger(c,"guess");if(n==g){credit(p,bet*5);msg(c.getSource(),"ทอยได้ "+n+"! ชนะ รับ "+(bet*5)+" G");}else msg(c.getSource(),"ทอยได้ "+n+" แพ้เดิมพัน");return 1;}))))
   .then(Commands.literal("wheel").then(Commands.argument("bet",LongArgumentType.longArg(1)).executes(c->{ServerPlayer p=self(c.getSource());long bet=LongArgumentType.getLong(c,"bet");if(!charge(p,bet))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("เงินไม่พอ")).create();int n=p.getRandom().nextInt(100);long mult=n<2?20:n<12?5:n<40?2:0;if(mult>0)credit(p,bet*mult);msg(c.getSource(),"Lucky Wheel "+n+" | "+(mult==0?"ไม่ได้รางวัล":"ได้รับ "+(bet*mult)+" G"));return 1;}))));
  d.register(Commands.literal("minigame")
   .then(Commands.literal("reaction").then(Commands.literal("start").executes(c->{ServerPlayer p=self(c.getSource());int target=p.getRandom().nextInt(9)+1;var t=data(c.getSource()).player(p.getUUID());t.putInt("reaction",target);t.putLong("reactionEnd",p.level().getGameTime()+200);data(c.getSource()).setDirty();msg(c.getSource(),"Reaction Test: พิมพ์ /minigame reaction hit "+target+" ภายใน 10 วินาที");return 1;}))
    .then(Commands.literal("hit").then(Commands.argument("number",IntegerArgumentType.integer(1,9)).executes(c->{ServerPlayer p=self(c.getSource());var t=data(c.getSource()).player(p.getUUID());if(t.getInt("reaction")==0||p.level().getGameTime()>t.getLong("reactionEnd")||IntegerArgumentType.getInteger(c,"number")!=t.getInt("reaction"))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("พลาดเป้าหมายหรือหมดเวลา")).create();t.putInt("reaction",0);credit(p,100);data(c.getSource()).setDirty();msg(c.getSource(),"สำเร็จ! ได้ 100 G");return 1;}))))
   .then(Commands.literal("rhythm").then(Commands.literal("start").executes(c->{ServerPlayer p=self(c.getSource());String[] keys={"up","down","left","right"};StringBuilder seq=new StringBuilder();for(int i=0;i<5;i++){if(i>0)seq.append(",");seq.append(keys[p.getRandom().nextInt(4)]);}var t=data(c.getSource()).player(p.getUUID());t.putString("rhythm",seq.toString());t.putLong("rhythmEnd",p.level().getGameTime()+600);data(c.getSource()).setDirty();msg(c.getSource(),"Rhythm sequence: "+seq+" | ตอบด้วย /minigame rhythm answer <sequence> ภายใน 30 วินาที");return 1;}))
    .then(Commands.literal("answer").then(Commands.argument("sequence",StringArgumentType.greedyString()).executes(c->{ServerPlayer p=self(c.getSource());var t=data(c.getSource()).player(p.getUUID());String expected=t.getString("rhythm");boolean ok=!expected.isEmpty()&&p.level().getGameTime()<=t.getLong("rhythmEnd")&&expected.equalsIgnoreCase(StringArgumentType.getString(c,"sequence").replace(" ",""));t.putString("rhythm","");if(ok){credit(p,150);msg(c.getSource(),"Rhythm สำเร็จ ได้ 150 G");}else msg(c.getSource(),"Rhythm ไม่สำเร็จ");data(c.getSource()).setDirty();return 1;}))))
   .then(Commands.literal("blackmarket").then(Commands.literal("start").executes(c->{ServerPlayer p=self(c.getSource());int code=1000+p.getRandom().nextInt(9000);var t=data(c.getSource()).player(p.getUUID());t.putInt("blackCode",code);t.putInt("blackTries",0);t.putLong("blackEnd",p.level().getGameTime()+600);data(c.getSource()).setDirty();msg(c.getSource(),"Black Market Challenge: จำรหัส 4 หลักนี้ไว้ "+code+" (30 วินาที)");return 1;}))
    .then(Commands.literal("solve").then(Commands.argument("code",IntegerArgumentType.integer(1000,9999)).executes(c->{ServerPlayer p=self(c.getSource());var t=data(c.getSource()).player(p.getUUID());t.putInt("blackTries",t.getInt("blackTries")+1);boolean ok=t.getInt("blackCode")==IntegerArgumentType.getInteger(c,"code")&&p.level().getGameTime()<=t.getLong("blackEnd")&&t.getInt("blackTries")<=3;t.putInt("blackCode",0);if(ok){t.putInt("blackRep",t.getInt("blackRep")+5);give(p,new ItemStack(Items.DIAMOND,4));msg(c.getSource(),"ผ่านด่าน ได้ Diamond 4 และ Black Market reputation +5");}else msg(c.getSource(),"ไม่สำเร็จ");data(c.getSource()).setDirty();return 1;})))));
  d.register(Commands.literal("house")
   .then(Commands.literal("buy").then(Commands.argument("price",LongArgumentType.longArg(1)).executes(c->{ServerPlayer p=self(c.getSource());long price=LongArgumentType.getLong(c,"price");if(!charge(p,price))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("เงินไม่พอ")).create();String id="H"+(data(c.getSource()).houses.size()+1);CompoundTag h=new CompoundTag();h.putUUID("owner",p.getUUID());h.putInt("x",p.blockPosition().getX());h.putInt("y",p.blockPosition().getY());h.putInt("z",p.blockPosition().getZ());h.putString("dimension",p.level().dimension().location().toString());h.putLong("paid",price);data(c.getSource()).houses.put(id,h);data(c.getSource()).setDirty();msg(c.getSource(),"ซื้อบ้าน "+id+" ที่ตำแหน่งปัจจุบันแล้ว");return 1;})))
   .then(Commands.literal("visit").then(Commands.argument("id",StringArgumentType.word()).executes(c->{ServerPlayer p=self(c.getSource());CompoundTag h=data(c.getSource()).houses.get(StringArgumentType.getString(c,"id"));if(h==null||!h.getUUID("owner").equals(p.getUUID()))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("ไม่พบบ้านของคุณ")).create();if(!p.level().dimension().location().toString().equals(h.getString("dimension")))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("บ้านอยู่คนละมิติ")).create();p.teleportTo(h.getInt("x")+0.5,h.getInt("y")+1,h.getInt("z")+0.5);return 1;})))
   .then(Commands.literal("list").executes(c->{data(c.getSource()).houses.forEach((id,h)->msg(c.getSource(),id+" owner="+h.getUUID("owner")+" @ "+h.getInt("x")+","+h.getInt("y")+","+h.getInt("z")));return 1;})));
  d.register(Commands.literal("tax")
   .then(Commands.literal("info").executes(c->{msg(c.getSource(),"Tax rate "+(data(c.getSource()).taxRate*100)+"% | City treasury "+data(c.getSource()).treasury+" G");return 1;}))
   .then(Commands.literal("rate").requires(s->s.hasPermission(2)).then(Commands.argument("percent",DoubleArgumentType.doubleArg(0,50)).executes(c->{data(c.getSource()).taxRate=DoubleArgumentType.getDouble(c,"percent")/100.0;data(c.getSource()).setDirty();msg(c.getSource(),"ตั้งภาษีแล้ว");return 1;}))));
  d.register(Commands.literal("profession")
   .then(Commands.literal("choose").then(Commands.argument("job",StringArgumentType.word()).executes(c->{String j=StringArgumentType.getString(c,"job");if(!List.of("blacksmith","miner","farmer","fisher","alchemist","lumberjack").contains(j))throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("อาชีพ: blacksmith miner farmer fisher alchemist lumberjack")).create();var t=data(c.getSource()).player(self(c.getSource()).getUUID());t.putString("profession",j);data(c.getSource()).setDirty();msg(c.getSource(),"เลือกอาชีพ "+j);return 1;})))
   .then(Commands.literal("info").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());msg(c.getSource(),"Profession "+t.getString("profession")+" Lv."+t.getInt("professionLevel")+" XP "+t.getInt("professionXp"));return 1;}))
   .then(Commands.literal("xp").requires(s->s.hasPermission(2)).then(Commands.argument("player",EntityArgument.player()).then(Commands.argument("amount",IntegerArgumentType.integer(1)).executes(c->{var t=data(c.getSource()).player(EntityArgument.getPlayer(c,"player").getUUID());int xp=t.getInt("professionXp")+IntegerArgumentType.getInteger(c,"amount");t.putInt("professionXp",xp);while(xp>=t.getInt("professionLevel")*100){xp-=t.getInt("professionLevel")*100;t.putInt("professionLevel",t.getInt("professionLevel")+1);}t.putInt("professionXp",xp);data(c.getSource()).setDirty();return 1;})))));
  d.register(Commands.literal("reputation").executes(c->{var t=data(c.getSource()).player(self(c.getSource()).getUUID());msg(c.getSource(),"Guild "+t.getInt("guildRep")+" | Merchant "+t.getInt("merchantRep")+" | Black Market "+t.getInt("blackRep"));return 1;}));
  d.register(Commands.literal("kingdom")
   .then(Commands.literal("status").executes(c->{RPGData r=data(c.getSource());msg(c.getSource(),r.eventName.isEmpty()?"ไม่มี event ที่กำลังทำงาน":"Event: "+r.eventName+" จบที่ tick "+r.eventEnd);return 1;}))
   .then(Commands.literal("start").requires(s->s.hasPermission(2)).then(Commands.argument("name",StringArgumentType.greedyString()).executes(c->{RPGData r=data(c.getSource());r.eventName=StringArgumentType.getString(c,"name");r.eventEnd=c.getSource().getLevel().getGameTime()+24000;r.setDirty();msg(c.getSource(),"เริ่ม Kingdom Event: "+r.eventName+" (1 วันในเกม)");return 1;})))
   .then(Commands.literal("stop").requires(s->s.hasPermission(2)).executes(c->{RPGData r=data(c.getSource());r.eventName="";r.eventEnd=0;r.setDirty();msg(c.getSource(),"หยุด event แล้ว");return 1;})));
 }
}